tiles.chartQuery:
WITH roots AS (
          SELECT span_trace_id, MIN(p_timestamp) AS started_at, MAX("gen_ai.agent.name") AS agent, MAX(span_duration_ns) AS duration_ns, MAX(span_status_code) AS status_code FROM $traces_dataset WHERE "mastra.span.type" = 'agent_run' GROUP BY span_trace_id
        ), usage AS (
          SELECT span_trace_id, MAX(COALESCE("gen_ai.request.model", "gen_ai.response.model")) AS model, SUM(CAST("gen_ai.usage.input_tokens" AS DOUBLE)) AS input_tokens, SUM(CAST("gen_ai.usage.output_tokens" AS DOUBLE)) AS output_tokens, SUM(CAST("gen_ai.usage.reasoning_tokens" AS DOUBLE)) AS reasoning_tokens, SUM(agent_cost(CASE WHEN "gen_ai.provider.name" LIKE 'openai%' THEN 'openai' ELSE "gen_ai.provider.name" END, COALESCE("gen_ai.request.model", "gen_ai.response.model"), CAST("gen_ai.usage.input_tokens" AS DOUBLE), CAST("gen_ai.usage.output_tokens" AS DOUBLE), p_timestamp)) AS cost_usd FROM $traces_dataset WHERE "mastra.span.type" = 'model_generation' AND "gen_ai.usage.input_tokens" IS NOT NULL GROUP BY span_trace_id
        ), tool_stats AS (
          SELECT span_trace_id, COUNT(*) AS tool_calls, SUM(CASE WHEN span_status_code = 2 THEN 1 ELSE 0 END) AS tool_errors FROM $traces_dataset WHERE "mastra.span.type" = 'tool_call' GROUP BY span_trace_id
        )
        SELECT r.started_at, r.agent, r.span_trace_id, u.model, ROUND(r.duration_ns / 1000000000.0, 3) AS duration_s, CASE WHEN r.status_code = 2 THEN 'error' ELSE 'success' END AS outcome, COALESCE(t.tool_calls, 0) AS tool_calls, COALESCE(t.tool_errors, 0) AS tool_errors, u.input_tokens, u.output_tokens, u.reasoning_tokens, ROUND(u.cost_usd, 6) AS cost_usd FROM roots r LEFT JOIN usage u ON r.span_trace_id = u.span_trace_id LEFT JOIN tool_stats t ON r.span_trace_id = t.span_trace_id ORDER BY r.started_at DESC LIMIT 50
